package com.bank.filter;

import java.util.List;

// Mirrors Boto3: {"Name": "...", "Values": [...]}. Values = OR; filters = AND.
public class Filter {
    private final String name;
    private final List<String> values;

    public Filter(String name, List<String> values) {
        this.name = name;
        this.values = values;
    }

    public String getName() { return name; }
    public List<String> getValues() { return values; }

    // Evaluate this one filter against an instance (as AWS would, server-side).
    public boolean matches(Instance inst) {
        String actual;
        if ("instance-state-name".equals(name)) {
            actual = inst.getState();
        } else if (name.startsWith("tag:")) {
            actual = inst.getTags().get(name.substring(4));
        } else if ("tag-key".equals(name)) {
            // match presence of ANY of the given tag keys
            return values.stream().anyMatch(k -> inst.getTags().containsKey(k));
        } else {
            return false;
        }
        return actual != null && values.contains(actual);  // OR within values
    }
}
