package com.bank.filter;

import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

// Simulates the AWS API: filters are applied at the "server" — only matches returned.
public class FilterableRegistry {
    private static final Logger log = Logger.getLogger(FilterableRegistry.class.getName());
    private final List<Instance> all;

    public FilterableRegistry(List<Instance> all) {
        this.all = all;
    }

    // AND across all filters; returns only matching instances (small result set).
    public List<Instance> describe(List<Filter> filters) {
        List<Instance> result = all.stream()
            .filter(inst -> filters.stream().allMatch(f -> f.matches(inst)))
            .collect(Collectors.toList());
        log.fine(() -> "Server evaluated " + all.size() + " instances, returned "
            + result.size() + " matches");
        return result;
    }
}
