package com.bank.filter;

import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class GovernanceJobs {
    private static final Logger log = Logger.getLogger(GovernanceJobs.class.getName());
    private final FilterableRegistry registry;

    public GovernanceJobs(FilterableRegistry registry) {
        this.registry = registry;
    }

    public List<String> runningProduction() {
        List<Instance> m = registry.describe(List.of(
            new Filter("tag:Environment", List.of("Production")),
            new Filter("instance-state-name", List.of("running"))));
        List<String> ids = m.stream().map(Instance::getId).collect(Collectors.toList());
        log.info(() -> "Inventory: running Production = " + ids);
        return ids;
    }

    public List<String> stoppedDev() {
        List<Instance> m = registry.describe(List.of(
            new Filter("tag:Environment", List.of("Development")),
            new Filter("instance-state-name", List.of("stopped"))));
        List<String> ids = m.stream().map(Instance::getId).collect(Collectors.toList());
        log.warning(() -> "Cleanup candidates: stopped Dev = " + ids);
        return ids;
    }

    public List<String> missingOwnerTag() {
        // Server-side narrow to any state, then residual client-side check for Owner.
        List<Instance> m = registry.describe(List.of(
            new Filter("instance-state-name", List.of("running", "stopped"))));
        List<String> ids = m.stream()
            .filter(i -> !i.getTags().containsKey("Owner"))
            .map(Instance::getId).collect(Collectors.toList());
        log.severe(() -> "Compliance VIOLATION: missing Owner tag = " + ids);
        return ids;
    }
}
