package com.bank.filter;

import java.util.List;
import java.util.Map;
import java.util.logging.*;

public class ServerSideFilterDemo {
    private static final Logger log = Logger.getLogger(ServerSideFilterDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Instance> all = List.of(
            new Instance("i-01", "running", Map.of("Environment", "Production", "Owner", "rajesh")),
            new Instance("i-02", "stopped", Map.of("Environment", "Development", "Owner", "priya")),
            new Instance("i-03", "running", Map.of("Environment", "Production")),  // no Owner!
            new Instance("i-04", "stopped", Map.of("Environment", "Development")), // no Owner!
            new Instance("i-05", "running", Map.of("Environment", "Staging", "Owner", "ops")));

        FilterableRegistry registry = new FilterableRegistry(all);
        GovernanceJobs jobs = new GovernanceJobs(registry);

        log.info("National Bank of India — governance jobs via server-side filters");
        jobs.runningProduction();
        jobs.stoppedDev();
        jobs.missingOwnerTag();
    }
}
